// Resolve o UC do canal
// 1. Se canal_id ja for UCxxx, usa direto
// 2. Senao, pega melhor match do search result
const ch = $('loop-by-channel').item.json;
const cidRaw = String(ch.canal_id || '').trim();
const isAlreadyUC = cidRaw.startsWith('UC') && cidRaw.length >= 22;

if (isAlreadyUC) {
  return [{ json: { ...ch, canal_id_anterior: cidRaw, canal_id_uc: cidRaw, match_via: 'direct' } }];
}

const resp = $input.first().json;
const items = Array.isArray(resp.items) ? resp.items : [];
if (items.length === 0) {
  return [];
}

const normalize = s => String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
const targetName = normalize(ch.nome_canal || ch.canal_id);

let best = null;
for (const it of items) {
  const title = normalize(it.snippet?.title || it.snippet?.channelTitle);
  if (targetName && (title.includes(targetName) || targetName.includes(title))) { best = it; break; }
}
if (!best) best = items[0];

const uc = best?.id?.channelId || best?.snippet?.channelId;
if (!uc) return [];

return [{ json: { ...ch, canal_id_anterior: cidRaw, canal_id_uc: uc, match_via: 'search', search_title: best?.snippet?.title || '' } }];

const ch = $('resolve-uc').item.json;
const resp = $input.first().json;
const items = Array.isArray(resp.items) ? resp.items : [];
const yt = items[0];
if (!yt) return [];

const subs = parseInt(yt.statistics?.subscriberCount || '0', 10);
const totalVideos = parseInt(yt.statistics?.videoCount || '0', 10);
const totalViews = parseInt(yt.statistics?.viewCount || '0', 10);
const sq = s => String(s||'').replace(/'/g, "''");

return [{
  json: {
    ...ch,
    canal_id_real: yt.id || ch.canal_id_uc,
    nome_canal_real: sq(yt.snippet?.title || ch.nome_canal || yt.id),
    canal_country: String(yt.snippet?.country || '').toUpperCase(),
    inscritos: subs,
    total_videos: totalVideos,
    total_views: totalViews,
    views_medio: totalVideos > 0 ? Math.round(totalViews / totalVideos) : 0
  }
}];

const channel = $('extract-channel-stats').item.json;
const search = $input.first().json;
const items = Array.isArray(search.items) ? search.items : [];
const sq = s => String(s||'').replace(/'/g, "''");
const out = [];
for (const it of items) {
  if (it.id?.kind !== 'youtube#video' || !it.id?.videoId) continue;
  out.push({
    json: {
      canal_id: channel.canal_id_real,
      nome_canal: channel.nome_canal_real || '',
      nicho: channel.nicho_alvo || '',
      video_id: it.id.videoId,
      url_video: `https://www.youtube.com/watch?v=${it.id.videoId}`,
      titulo_original: sq(it.snippet?.title || ''),
      descricao_original: sq((it.snippet?.description || '').substring(0, 500)),
      thumbnail_url: it.snippet?.thumbnails?.high?.url || it.snippet?.thumbnails?.default?.url || ''
    }
  });
}
return out;

