const allVideos = $('extract-video-list').all().map(i => i.json);
const existing = $input.all().map(i => String(i.json.video_id || '')).filter(Boolean);
const existingSet = new Set(existing);
const news = allVideos.filter(v => v.video_id && !existingSet.has(String(v.video_id)));
return news.map(v => ({ json: v }));

// Recebe TODOS os items de uma vez (modo batch)
function iso8601ToSeconds(iso) {
  if (!iso || typeof iso !== 'string') return 0;
  const m = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!m) return 0;
  return (parseInt(m[1]||'0',10))*3600 + (parseInt(m[2]||'0',10))*60 + (parseInt(m[3]||'0',10));
}

const MIN_VIEWS_DISCOVERY = 5000;

const metas = $('filter-new-only').all().map(i => i.json);
const metaByVid = new Map(metas.map(m => [String(m.video_id), m]));
const out = [];

for (const inp of $input.all()) {
  const details = inp.json;
  const item = (details.items || [])[0];
  if (!item) continue;

  const dur = iso8601ToSeconds(item.contentDetails?.duration || '');
  if (dur < 60 || dur > 7200) continue;

  const vid = String(item.id || '');
  const meta = metaByVid.get(vid);
  if (!meta) continue;

  if (String(meta.nicho || '').toLowerCase() === 'copa') {
    const tituloCopa = String(item.snippet?.title || meta.titulo_original || '').toLowerCase();
    const ehHighlight = /(melhores momentos|gols|gol de|todos os gols|resumo|highlights|melhor momento|golaco|golaço)/.test(tituloCopa);
    if (!ehHighlight) continue;
  }

  const defLang = String(item.snippet?.defaultLanguage || '').toLowerCase();
  const defAudio = String(item.snippet?.defaultAudioLanguage || '').toLowerCase();
  const titulo = String(item.snippet?.title || meta.titulo_original || '').toLowerCase();
  const desc = String(item.snippet?.description || meta.descricao_original || '').toLowerCase();
  const blob = titulo + ' ' + desc;

  const langDeclaresPT = defLang.startsWith('pt') || defAudio.startsWith('pt');
  const langDeclaresNonPT = (defLang && !defLang.startsWith('pt')) || (defAudio && !defAudio.startsWith('pt'));
  const hasPTAccents = /[áéíóúâêôãõç]/.test(blob);
  const hasPTWords = /\b(que|para|com|você|voce|não|nao|mas|sou|aqui|gente|nós|nos|vou|fazer|sobre|pessoal|brasil|brasileiro|isso|hoje|tudo|porque|porquê|como|quando|onde)\b/.test(blob);
  const enDominance = (blob.match(/\b(the|and|you|for|with|this|that|how|what|video|subscribe|channel|today|guys|because)\b/g) || []).length;

  let isPT;
  if (langDeclaresPT) isPT = true;
  else if (langDeclaresNonPT) isPT = false;
  else isPT = (hasPTAccents || hasPTWords) && enDominance < 3;

  if (!isPT) continue;

  const views = parseInt(item.statistics?.viewCount || '0', 10);
  const likes = parseInt(item.statistics?.likeCount || '0', 10);
  const coments = parseInt(item.statistics?.commentCount || '0', 10);

  if (views < MIN_VIEWS_DISCOVERY) continue;

  out.push({
    json: {
      ...meta,
      duracao_segundos: dur,
      views, likes, comentarios: coments,
      engagement_pct: views > 0 ? Number(((likes + coments) / views * 100).toFixed(2)) : 0,
      idioma_detectado: langDeclaresPT ? (defAudio || defLang) : 'pt-heuristica'
    }
  });
}
return out;

